QUESTIONS = []
def q(topic, level, prompt, options, correct, why):
    QUESTIONS.append(dict(id=f'q{len(QUESTIONS)+1:02}',topic=topic,level=level,prompt=prompt,options=options,correct=correct,why=why))

q('fundamentos','Conceito','Qual característica é central na definição de manipulador industrial apresentada na aula?', ['Reprogramabilidade para diferentes tarefas','Ter forma humana','Usar uma rede neural','Operar sem fonte de energia'],0,'A definição enfatiza um manipulador reprogramável e multifuncional. Aparência humana e IA não são requisitos.')
q('fundamentos','Aplicação','Uma célula repete posições ensinadas sem decidir uma nova rota. Como descrevê-la?', ['Automaticamente executa um programa','É necessariamente autônoma em ambiente desconhecido','Não pode ser robótica','É necessariamente teleoperada'],0,'Execução automática de uma sequência não implica autonomia para decidir diante de mudanças.')
q('historia','Conceito','O que distingue Shakey nos marcos da aula?', ['Percepção e planejamento para navegação','Primeiro uso de cartões em um tear','Criação das leis de Asimov','Uso obrigatório de seis juntas industriais'],0,'Shakey é associado à integração de percepção, modelo e planejamento em um robô móvel.')
q('historia','Conceito','Qual associação histórica aparece no material?', ['PUMA — manipulador para montagem','Aibo — primeiro tear perfurado','Jacquard — robô em Marte','Sojourner — máquina diferencial'],0,'A aula apresenta PUMA como Programmable Universal Machine for Assembly. Sojourner está ligado à missão Pathfinder.')
q('computacao-ficcao','Conceito','Qual correção é necessária ao estudar o slide sobre Babbage?', ['Distinguir máquina diferencial de máquina analítica','Atribuir ambas ao século XX','Tratar ambas como redes neurais','Afirmar que cartões não representam instruções'],0,'A diferencial foi concebida para tabelas; a analítica é associada a computação programável de propósito geral.')
q('computacao-ficcao','Aplicação','As três leis de Asimov substituem a análise de riscos de um robô?', ['Não; são regras de ficção','Sim, se escritas no código em C','Sim, em qualquer cobot','Sim, se o robô reconhecer pessoas'],0,'As leis são narrativas. Segurança técnica exige avaliação da aplicação, medidas e validação.')
q('paradigmas','Aplicação','Um planejador escolhe a rota e uma camada local evita obstáculos. Qual arquitetura representa isso?', ['Híbrida','Somente sequência mecânica fixa','Exclusivamente teleoperada','Somente deliberativa sem reação local'],0,'Combina planejamento global com resposta local ao ambiente.')
q('paradigmas','Conceito','Qual robô da aula utiliza percepção–ação?', ['PINÓQUIO','SOFIA','ASIMOV, exclusivamente','ASIMO, identificado com ASIMOV'],0,'PINÓQUIO é apresentado como percepção–ação; SOFIA como percepção–planejamento–ação e ASIMOV como híbrido.')
q('matematica','Cálculo','Uma carga de 2 kg está a 0,4 m do eixo com braço horizontal. Usando g = 9,81 m/s², qual torque equilibra só essa carga?', ['7,848 N·m','0,8 N·m','19,62 N·m','78,48 N·m'],0,'τ = mgr = 2 × 9,81 × 0,4 = 7,848 N·m. A conta não inclui braço, atrito ou aceleração.')
q('matematica','Cálculo','60 rpm equivalem a:', ['2π rad/s','60 rad/s','π/60 rad/s','360 rad/s'],0,'60 rpm é uma volta por segundo. Uma volta corresponde a 2π rad.')
q('estrutura','Conceito','Qual componente executa diretamente a tarefa de soldar ou agarrar?', ['Órgão terminal','Base','Elo de entrada de qualquer junta','Rolamento de suporte'],0,'O órgão terminal é a ferramenta ou garra conectada à extremidade do robô.')
q('estrutura','Aplicação','Uma transmissão leva movimento de um motor na base até uma junta distante. Qual efeito ela pode trazer?', ['Reduzir massa móvel, mas introduzir perdas e elasticidade','Eliminar toda deformação estrutural','Garantir precisão infinita','Eliminar a necessidade de controle'],0,'Mover o motor para a base pode reduzir massa em movimento, mas a transmissão precisa ser avaliada por perdas, folga e elasticidade.')
q('juntas','Conceito','Por que uma junta helicoidal ideal tem um grau de liberdade?', ['Rotação e translação são vinculadas pelo passo','Não permite translação','Tem dois motores independentes','Todo mecanismo com rotação tem três GL'],0,'Uma coordenada determina ambos os movimentos. A independência, e não a quantidade de movimentos visíveis, define GL.')
q('juntas','Cálculo','Uma cadeia aberta RRPS, sem vínculos adicionais, tem quantos GL? S é esférica.', ['6','4','5','7'],0,'R + R + P + S = 1 + 1 + 1 + 3 = 6. A junta esférica ideal permite três rotações independentes.')
q('juntas','Conceito','Qual afirmação sobre juntas planares respeita as convenções?', ['A geral tem 3 GL; a combinação de duas P da apostila tem 2','Toda planar tem exatamente 2 GL em qualquer texto','Uma planar geral nunca gira','As duas convenções significam sempre o mesmo mecanismo'],0,'Uma junta planar geral permite x, y e rotação. A apostila chama de planar um arranjo de duas prismáticas.')
q('configuracoes','Conceito','Qual arquitetura possui três juntas principais prismáticas ortogonais?', ['Cartesiana','Polar','Articulada vertical','SCARA'],0,'PPP é a configuração cartesiana ideal. Polar e SCARA podem ser RRP, com eixos dispostos de formas diferentes.')
q('configuracoes','Aplicação','Por que RRP sozinho não distingue polar de SCARA?', ['É necessário saber a orientação dos eixos','Polar tem obrigatoriamente seis P','SCARA não possui nenhuma rotação','As letras identificam o fabricante'],0,'A ordem dos tipos de junta não informa toda a geometria. O arranjo dos eixos muda o movimento e o volume.')
q('configuracoes','Aplicação','O gráfico qualitativo da aula 06 permite concluir velocidades reais de fabricantes?', ['Não; ele é um índice didático ilustrativo','Sim, cada barra está em m/s','Sim, basta multiplicar por 100','Somente para o Delta'],0,'O próprio slide indica que a comparação é qualitativa e não representa especificações de fabricantes.')
q('workspace','Cálculo','Um pórtico tem cursos de 0,5 m, 0,4 m e 0,3 m. Qual volume ideal?', ['0,06 m³','1,2 m³','0,6 m³','0,12 m³'],0,'V = 0,5 × 0,4 × 0,3 = 0,06 m³, usando eixos ortogonais e cursos independentes. Limites e interferências reduzem a região utilizável.')
q('workspace','Cálculo','Uma região cilíndrica de volta completa tem r_max = 0,8 m, r_min = 0,2 m, h = 0,5 m. Qual volume?', ['0,3π m³','0,32π m³','0,6π m³','π m³'],0,'V = π(0,8² − 0,2²)0,5 = π(0,64 − 0,04)0,5 = 0,3π m³.')
q('workspace','Aplicação','Um alvo é alcançável, mas não com a orientação exigida. O que isso mostra?', ['Alcance de posição e destreza de orientação são diferentes','A cinemática inversa é sempre única','O robô tem resolução zero','Não existe espaço de trabalho'],0,'Posição alcançável não garante todas as orientações desejadas naquela posição.')
q('garras','Cálculo','Dois dedos seguram 1 kg verticalmente, μ = 0,3 e margem S = 2. Sem aceleração, qual normal mínima por dedo? g = 9,81.', ['32,7 N','65,4 N por dedo','3,27 N','9,81 N'],0,'N ≥ Smg/(pμ) = 2×1×9,81/(2×0,3) = 32,7 N por contato. A soma das normais é 65,4 N.')
q('garras','Aplicação','Qual escolha exige verificar porosidade e vazamentos do objeto?', ['Ventosa','Toda engrenagem do redutor','Encoder absoluto','Potenciômetro de junta'],0,'Uma ventosa depende da manutenção de diferença de pressão e vedação; porosidade pode comprometer a preensão.')
q('atuadores','Cálculo','Δp = 500 kPa e área efetiva = 0,001 m². Qual força ideal do cilindro?', ['500 N','0,5 N','500 kg','5.000 N'],0,'500 kPa = 500.000 Pa. F = ΔpA = 500 N. Quilograma mede massa, não força.')
q('atuadores','Conceito','O que caracteriza acionamento indireto?', ['Um mecanismo transmite o movimento entre atuador e junta','O motor não recebe energia','Não há controlador','A junta deixa de se mover'],0,'Redutores, cabos, correias e outros mecanismos podem transmitir e adaptar o movimento.')
q('motores','Cálculo','Motor com passo completo de 1,8°. Quantos passos completos fazem uma volta?', ['200','180','360','2.000'],0,'360/1,8 = 200. Microstepping muda a quantidade de comandos, não essa definição de passo completo.')
q('motores','Aplicação','Um motor de passo em malha aberta perde passos. O que pode acontecer?', ['A posição estimada por contagem fica diferente da real','O controlador sempre detecta automaticamente','O encoder absoluto é obrigatório para existir movimento','A precisão aumenta'],0,'Sem medição apropriada, o software pode continuar contando comandos como se todos fossem executados.')
q('motores','Conceito','No modelo da aula τ = Kt i, aumentar corrente produz qual tendência?', ['Aumenta o torque no modelo, respeitando limites','Diminui sempre o torque','Muda apenas o número de bits do encoder','Elimina a força contraeletromotriz'],0,'Torque é proporcional à corrente no modelo simplificado. Limites térmicos e do driver continuam importantes.')
q('transmissoes','Cálculo','τ_motor = 1 N·m, N = 50 e η = 0,8. Torque idealizado de saída:', ['40 N·m','50 N·m','0,016 N·m','62,5 N·m'],0,'τ_saída = ηNτ_motor = 0,8×50×1 = 40 N·m.')
q('transmissoes','Cálculo','Motor a 3.000 rpm com redução N = 50. Velocidade de saída:', ['60 rpm','150.000 rpm','600 rpm','50 rpm'],0,'ω_saída = ω_motor/N = 3.000/50 = 60 rpm.')
q('transmissoes','Conceito','Após inverter o motor, a saída demora a responder devido a espaço entre dentes. Qual efeito?', ['Folga / backlash','Cinemática inversa','Amostragem de câmera','Código Gray'],0,'Backlash é um intervalo de movimento de entrada antes da resposta da saída, especialmente nas reversões.')
q('sensores','Conceito','Qual sensor é mais diretamente associado à variação de resistência por deformação?', ['Strain gauge','Encoder incremental óptico','Câmera RGB','Tacômetro ideal'],0,'O strain gauge varia resistência com deformação e pode integrar uma medição de força após calibração.')
q('sensores','Cálculo','Eco ultrassônico leva 4 ms. Com c = 343 m/s, qual distância ao alvo?', ['0,686 m','1,372 m','68,6 m','0,343 m'],0,'d = ct/2 = 343×0,004/2 = 0,686 m. O tempo inclui ida e volta.')
q('encoders','Cálculo','Um encoder absoluto tem 12 bits por volta. Quantas posições e qual incremento aproximado?', ['4.096 posições; 0,0879°','12 posições; 30°','1.024 posições; 0,3516°','4.096 posições; 12°'],0,'2¹² = 4.096; 360/4.096 ≈ 0,0879°. Isso não é automaticamente a precisão absoluta.')
q('encoders','Cálculo','1.000 ciclos por volta em quadratura, contagem x4. Quantas contagens por volta?', ['4.000','1.000','250','2.000'],0,'Na definição dada, x4 conta quatro bordas por ciclo. Sempre confirme como o fabricante define PPR/CPR.')
q('encoders','Conceito','O que distingue posições vizinhas em código Gray?', ['Apenas um bit muda','Todos os bits mudam','Nunca há erro elétrico','O código é sempre uma medida analógica'],0,'A mudança de um bit reduz ambiguidade de transições; não elimina todo ruído.')
q('controle','Cálculo','Referência 100°, medição 97°. Para e = r − y, qual erro?', ['3°','−3°','197°','0°'],0,'e = 100 − 97 = 3°. O sinal informa o sentido do desvio nessa convenção.')
q('controle','Conceito','Qual termo do PID acumula o erro?', ['Integral','Proporcional','Derivativo','Driver'],0,'I acumula erro ao longo do tempo. Windup pode ocorrer quando a ação satura e a integral continua crescendo.')
q('controle','Cálculo','Ts = 5 ms. Qual frequência de amostragem?', ['200 Hz','5 Hz','0,2 Hz','5.000 Hz'],0,'Converta 5 ms para 0,005 s. f_s = 1/Ts = 200 Hz.')
q('controle','Cálculo','e = 2, e_anterior = 1, Ts = 0,1; I_anterior = 0; Kp = 3, Ki = 1, Kd = 0,2. Qual u discreto antes de saturação?', ['8,2','6,2','2,2','10'],0,'I = 0,2; D = (2−1)/0,1 = 10. u = 3×2 + 1×0,2 + 0,2×10 = 8,2.')
q('embarcados','Conceito','O requisito principal de tempo real é:', ['Cumprir prazos de resposta definidos','Ter a maior frequência de CPU','Usar obrigatoriamente Linux','Processar imagens em toda tarefa'],0,'Tempo real trata de prazos e previsibilidade, não apenas velocidade média de processamento.')
q('embarcados','Aplicação','Por que separar visão e controle de motor entre computador e microcontrolador?', ['Para distribuir processamento e preservar prazos do controle','Para eliminar toda comunicação','Para dispensar sensores','Para tornar a fonte desnecessária'],0,'Visão pode demandar processamento variável, enquanto tarefas locais precisam responder em intervalos definidos.')
q('potencia','Cálculo','Quatro motores consomem 24 V × 5 A cada um. Qual soma nesses pontos de operação?', ['480 W','120 W','20 W','96 W'],0,'Cada motor consome 120 W. Quatro somam 480 W, antes de outras cargas e perdas.')
q('potencia','Cálculo','Bateria 12 V, 10 Ah, 80% utilizável, carga média 60 W. Autonomia estimada:', ['1,6 h','2 h','0,16 h','8 h'],0,'E nominal = 120 Wh; utilizável = 96 Wh; t = 96/60 = 1,6 h.')
q('potencia','Aplicação','Qual componente adapta sinais lógicos para controlar corrente de um motor?', ['Driver de potência','Encoder','TCP','Elemento finito'],0,'O driver controla potência. A saída lógica do microcontrolador não deve alimentar diretamente um motor de vários amperes.')
q('potencia','Cálculo','PWM ideal entre 0 e 12 V com duty cycle de 25%. Qual tensão média?', ['3 V','12 V','0,25 V','9 V'],0,'Média ideal = DV = 0,25×12 = 3 V. O sinal instantâneo continua chaveando, e velocidade não é necessariamente 25%.')
q('comunicacao','Aplicação','Qual interface ROS é apropriada para navegação com feedback e cancelamento?', ['Action','Somente um service curto','Um fio de alimentação','Um ADC'],0,'Actions organizam metas demoradas com feedback, resultado e possibilidade de cancelamento.')
q('comunicacao','Conceito','Qual afirmação sobre RS-485 é correta?', ['Define uma camada elétrica; é preciso definir também o protocolo','É uma linguagem de programação','Garante qualquer prazo de tempo real','Dispensa considerar terminação e rede'],0,'RS-485 define sinalização elétrica; estrutura de mensagens e comportamento da aplicação exigem regras adicionais.')
q('cinematica','Cálculo','Braço planar L1 = L2 = 1 m, q1 = 0°, q2 relativo = 90°. Qual posição?', ['(1, 1) m','(2, 0) m','(0, 2) m','(0, 0) m'],0,'x = cos 0 + cos 90 = 1; y = sen 0 + sen 90 = 1.')
q('cinematica','Conceito','A cinemática inversa sempre tem uma solução única?', ['Não; pode ter zero, uma, várias ou famílias de soluções','Sim, para qualquer pose','Sim, se existir um encoder','Não pode ter nenhuma solução em qualquer caso'],0,'Alcance, limites, redundância e geometria definem a existência e quantidade de soluções.')
q('jacobiano','Conceito','O Jacobiano relaciona diretamente:', ['Velocidades das juntas e do efetuador','Preço e potência da bateria','Massa e número de pixels','Apenas posições absolutas sem configuração'],0,'ẋ = J(q)q̇ é uma relação local que depende da configuração q.')
q('jacobiano','Aplicação','Para um Jacobiano retangular, como identificar singularidade?', ['Investigar perda de posto','Usar obrigatoriamente det(J)','Contar apenas letras R','Medir Ah da bateria'],0,'Determinante é um critério para matrizes quadradas. O conceito geral envolve posto e capacidade de movimento.')
q('jacobiano','Conceito','Um braço com 7 GL pode ser redundante para qual tarefa?', ['Pose espacial com seis variáveis independentes','Qualquer tarefa com oito variáveis independentes','Somente uma tarefa sem movimento','Nenhuma, pois redundância é impossível'],0,'Redundância é relativa às exigências da tarefa. Sete coordenadas podem exceder as seis necessárias à pose espacial.')
q('desempenho','Aplicação','Alvo 100 mm; resultados 102,0; 102,1; 102,0 mm. Qual leitura é mais adequada?', ['Bom agrupamento, com desvio sistemático do alvo','Má repetibilidade necessariamente','Precisão absoluta perfeita','Resolução infinita'],0,'As repetições ficam próximas entre si, mas a média está cerca de 2 mm além do alvo.')
q('desempenho','Cálculo','r = 0,5 m e pequeno Δθ = 0,1°. Quanto vale rΔθ aproximadamente?', ['0,873 mm','50 mm','0,05 mm','87,3 mm'],0,'0,1° = 0,001745 rad; 0,5×0,001745 = 0,000873 m = 0,873 mm.')
q('dinamica','Cálculo','Rigidez k = 10.000 N/m e força F = 20 N. Qual deformação linear?', ['2 mm','200 mm','0,2 m','20 mm'],0,'δ = F/k = 20/10.000 = 0,002 m = 2 mm. A relação usa um modelo linear em uma direção; outras posturas podem ter rigidez diferente.')
q('dinamica','Conceito','Por que um deslocamento curto pode ter perfil triangular de velocidade?', ['Não há distância suficiente para atingir e manter a velocidade máxima','O motor não tem corrente','O caminho precisa ter três cantos','Toda junta é esférica'],0,'Aceleração e desaceleração ocupam o movimento sem um patamar de velocidade constante.')
q('programacao','Aplicação','Para pintura ao longo de uma curva, qual aspecto precisa ser controlado?', ['O percurso contínuo e seu perfil de movimento','Só os pontos inicial e final','Apenas o nome do robô','Somente o número de elos'],0,'Pintura precisa do controle do percurso. PTP sozinho não especifica o caminho cartesiano entre extremos.')
q('programacao','Cálculo','Duas juntas movem 90° e 45° no mesmo tempo, sem aceleração. Qual relação entre velocidades?', ['A segunda tem metade da velocidade da primeira','A segunda tem o dobro','São iguais','A primeira precisa ficar parada'],0,'Velocidade = deslocamento/tempo. Com tempo igual, 45/90 = 1/2. Isso não garante trajetória cartesiana reta.')
q('visao','Conceito','Qual parâmetro pertence à calibração extrínseca?', ['Pose da câmera em relação ao robô','Quantidade de Ah da bateria','Somente distorção da lente','Duty cycle da ponte H'],0,'Extrínsecos relacionam referenciais. Distância focal, ponto principal e distorção pertencem ao modelo intrínseco.')
q('visao','Aplicação','Um limiar fixo separa bem uma linha sob uma luz e falha sob outra. Qual explicação é razoável?', ['A iluminação alterou as intensidades e a separação','A câmera necessariamente virou um encoder','O PID elimina toda alteração de imagem','Pixels são sempre medidas exatas em metros'],0,'Limiarização depende da distribuição de intensidades. Mudanças de iluminação podem exigir adaptação ou outro método.')
q('navegacao','Cálculo','Roda de raio 0,05 m a 120 rpm, sem deslizamento. Qual velocidade linear?', ['0,628 m/s','6 m/s','0,1 m/s','120 m/s'],0,'ω = 120×2π/60 = 4π rad/s; v = ωr = 0,2π ≈ 0,628 m/s.')
q('navegacao','Conceito','O que o SLAM estima simultaneamente?', ['Mapa e posição do robô','Somente corrente e tensão','Preço e vida útil','Apenas torque de uma garra'],0,'SLAM é localização e mapeamento simultâneos; as duas estimativas dependem uma da outra.')
q('ia','Conceito','Em aprendizado por reforço, a política é:', ['A regra aprendida de escolha de ações','Sempre uma tabela de tensão de bateria','Um conjunto de cartões perfurados obrigatório','A posição física de uma junta'],0,'A política determina ações a partir de estado ou observação, visando recompensa acumulada.')
q('ia','Aplicação','Uma política funciona em simulação e falha no robô. Qual problema é compatível?', ['Diferenças sim-to-real em dinâmica, ruído ou atrasos','Prova de que toda simulação é inútil','Ausência obrigatória de qualquer algoritmo','Garantia de que a falha é só na câmera'],0,'A simulação aproxima o mundo. Diferenças de atrito, parâmetros e sensores podem reduzir a robustez.')
q('seguranca','Aplicação','Um braço colaborativo recebe uma ferramenta cortante. O que é necessário considerar?', ['Reavaliar os riscos da aplicação completa','Presumir que o nome cobot garante segurança','Retirar sensores por ter baixa potência','Usar as leis de Asimov como única proteção'],0,'Ferramenta, peça, ambiente e movimento modificam riscos. Segurança pertence à aplicação completa.')
q('seguranca','Aplicação','Ao perder comunicação, qual comportamento exige definição no projeto?', ['O estado seguro e a resposta ao timeout','Continuar sempre à última velocidade','Ignorar o erro se houver IA','Desligar tudo sem avaliar a carga'],0,'A resposta deve ser adequada ao risco; parar, manter estabilidade ou reter carga pode exigir ações específicas.')
q('aplicacoes','Cálculo','Uma peça por ciclo, ciclo de 12 s e 80% de tempo produtivo. Qual produção estimada?', ['240 peças/h','300 peças/h efetivas','80 peças/h','3.600 peças/h'],0,'Ideal = 3.600/12 = 300; estimativa com 80% = 240 peças/h, sem incluir outros fatores.')
q('aplicacoes','Aplicação','Para um robô agrícola, qual requisito distingue o ambiente de uma bancada controlada?', ['Variação de terreno, luz e características das plantas','Ausência garantida de ruído','Mesma iluminação em todos os horários','Não precisar perceber o ambiente'],0,'Ambientes agrícolas introduzem variabilidade que precisa orientar percepção e locomoção.')
q('projeto','Conceito','Quais cálculos são pedidos na etapa de dimensionamento da aula?', ['P = τω; E = Pt; v = ωr','Somente soma dos preços','Apenas número de integrantes','Apenas quantidade de pixels'],0,'A atividade solicita ao menos potência, energia e velocidade, com unidades e hipóteses.')
q('projeto','Aplicação','Qual requisito é mais verificável para uma proposta de logística?', ['Transportar até 2 kg a 0,5 m/s em piso plano por 2 h','Ser o robô mais inteligente','Resolver todos os problemas industriais','Ter muitos sensores'],0,'Carga, velocidade, ambiente e autonomia são critérios mensuráveis que orientam o projeto.')
